clips=json.loads((R/'research/video-frames.json').read_text());assert len(clips)==len(profiles)==28
for c,(kind,observation,method,keywords,demo) in zip(clips,profiles):c.update(category=kind,observation=observation,inferred_method=method,keywords=keywords,demo=demo,confidence='프레임 관측은 높음 / 정확한 제작 파이프라인은 추정',sample_scope='길이의 약 5%, 40%, 80%에서 디코딩된 프레임. 전체 프레임/원본 타임라인 검증은 아님.')
(R/'research/video-analysis.json').write_text(json.dumps(clips,ensure_ascii=False,indent=2))
(R/'research/video-analysis-data.js').write_text('window.LUSION_VIDEO_REVIEW='+json.dumps(clips,ensure_ascii=False)+';\n')
md=['# 영상 프레임 기반 재분석\n\n28개 공개 MP4에서 시간 검증을 거친 84개 프레임을 추출하고 7개 콘택트시트를 직접 검토했다. 실제로 보이는 장면과 예상 구현을 분리한다. 프레임 3장으로 정확한 easing, FPS, 전체 컷 구성, 제작 툴을 확정하지 않는다.\n\n[영상 분석 열람기](../video-analysis.html) · [관측 데이터](../research/video-analysis.json)\n']
for i,c in enumerate(clips):
 name=c['local'].split('/assets/')[-1];md+=['\n## '+str(i+1)+'. '+name+'\n',f"\n- 원본: [{name}]({c['url']})\n- 메타데이터: {c['width']}×{c['height']}, {c['duration']:.3f}초.\n- **관측:** {c['observation']}\n- **분석 기반 제작 방식:** {c['inferred_method']}\n- 시스템 연결: {c['demo']}. [모션 실험실](../motion-lab.html), [컴포넌트](../components.html).\n",'\n'+' · '.join(f"[{f['time']:.2f}s](../{f['local']})" for f in c['frames'])+'\n']
md+=['\n## 수집/분석 검수\n\n브라우저에서 MP4를 Blob으로 로드해 정확한 시킹을 확보하고 requestVideoFrameCallback 후 캔버스에 기록했다. 목표 시각과 실제 currentTime이 0.25초 이내인지 검사한다. 초기 HTTP 시킹 검사는 원점 프레임을 반환해 폐기했으며 현재 파일들은 수정된 추출기로 모두 덮어썼다. UI 데모는 영상 속 AR/인물/개별 캠페인 전체를 복제한 것이 아니라 재사용 가능한 동작 패턴을 적용한다.\n']
(R/'media/video-analysis.md').write_text(''.join(md))
print('28 video observations / 84 timestamp-verified frames')
